export const CreateObjectView = observer(({ model }) => {
  const [selectedAssetId, setSelectedAssetId] = useState();

  const handleSelectAsset = event => {
    setSelectedAssetId(event.target.value);
  };

  const handleCreateObject = () => {
    model.createObject(selectedAssetId).then(() => {
      // Handle successful object creation here
    });

    model.setSelectedAsset(null);
    setSelectedAssetId(undefined);
  };

  const handleCleanupScene = () => {
    model.cleanupScene().then(() => {
      // Handle successful cleanup here
    });
  };

  return (
    <div id="object-creation">
      <label htmlFor="select-asset">Asset:</label>
      <input type="text" id="select-asset" value={selectedAssetId} onChange={handleSelectAsset} />
      <button id="create-object" onClick={handleCreateObject}>Create Object</button>
      <button id="cleanup-scene" onClick={handleCleanupScene}>Cleanup Scene</button>

      {model.availableAssets.map(asset => (
        <div key={asset.id}>
          {asset.name} ({asset.description})
        </div>
      ))}
    </div>
  );
});
```

