const botToken = 'YOUR_BOT_TOKEN';
const webhookUrl = 'YOUR_WEBHOOK_URL';

async function sendMessageToSlack(channel, message) {
  const payload = {
    text: message,
    username: 'my-bot', // Change this to the name you want to display for your bot
    icon_emoji: ':robot:' // Change this to the emoji you want to display next to your bot's name
  };

  try {
