To tackle this task, we will first define an array of homophone pairs and their correct replacements. Then, we will create a function that replaces homophones in a given string using regular expressions. Here's how the implementation might look like:

```swift
let homophones: [(String, String)] = [("there", "they're"), ("their", "there"), ("they're", "there"), ("your", "you're"), ("you're", "you"), ("knot", "not")]

func replaceHomophones(_ str: String) -> String {
    let regex = try! NSRegularExpression(pattern: "(?i)\\b(\\w+)\\b", options: .caseInsensitive)

    var result = ""
    for (from, to) in homophones {
        let range = NSRange(location: 0, length: str.utf16.count, in: str)

        while true {
            let match = regex.firstMatch(in: str, options: [], range: range)?.range
            guard let matchRange = Range(match!, in: str), matchRange != result.utf16.count..<str.utf16.count else { break }

            let replacement = String(str[matchRange.lowerBound..<min(matchRange.upperBound, str.utf16.index(matchRange.upperBound, offsetBy: from.utf16.count))])
            result.replaceSubrange(matchRange, with: replacement)
            let newRange = NSRange(location: result.utf16.index(after: matchRange.upperBound), length: result.utf16.distance(from: result.utf16.index(after: matchRange.upperBound), to: result.utf16.endIndex))
            range.location += newRange.length
        }

        result = String(result.prefix(upTo: result.utf16.index(before: str.utf16.lastIndex(of: to)))) + to + String(result.suffix(from: str.utf16.lastIndex(of: to)))
    }

    return result
}

