function tense = identify_tense(sentence)
    % Tokenize the sentence
    tokens = tokenize(sentence);

    % Perform part-of-speech tagging
    pos_tags = pos_tag(tokens);

    % Parse the dependency structure of the sentence
    deps = dependency_parse(tokens, pos_tags);

    % Extract the verb from the dependency parse tree
    verb_index = find(deps(:, 1) == 'VB');
    verb_token = tokens(verb_index);

    % Determine the tense based on the verb and its dependencies
